import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"FinOps Review — enumerated source for the FinOps Review assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/finops-review-question-set.md","filePath":"frameworks/finops-review-question-set.md"}'),s={name:"frameworks/finops-review-question-set.md"};function n(r,e,d,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="finops-review-—-enumerated-source-for-the-finops-review-assessment" tabindex="-1">FinOps Review — enumerated source for the FinOps Review assessment <a class="header-anchor" href="#finops-review-—-enumerated-source-for-the-finops-review-assessment" aria-label="Permalink to &quot;FinOps Review — enumerated source for the FinOps Review assessment&quot;">​</a></h1><p><strong>Enumerated 2026-08-01. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p><strong>Framework version:</strong> Not versioned by Microsoft — the FinOps Review assessment carries no release number. The extraction date above (2026-08-01) is the version, per <code>docs/frameworks/README.md</code>; re-date this line when this file is next re-verified.</p><p>This is the AB#6814 enumeration for target #9 in the audit&#39;s fourteen-assessment programme (<code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> §14): <em>&quot;FinOps Review — Cost surface exists … <code>waf.cost</code> (6 rules) + <code>caf.billing</code> (misnamed, holds cost rules).&quot;</em> Neither existing file scores against the FinOps Framework itself — they score WAF&#39;s Cost Optimization pillar and (mislabelled) cost-cleanup rules respectively. Per DQ12, no FinOps-Framework-shaped rule file is written until this enumeration exists.</p><h2 id="what-the-finops-review-is" tabindex="-1">What the FinOps Review is <a class="header-anchor" href="#what-the-finops-review-is" aria-label="Permalink to &quot;What the FinOps Review is&quot;">​</a></h2><p>The <strong>FinOps Review</strong> is an interactive assessment on the Microsoft Assessments platform (<a href="https://learn.microsoft.com/en-us/assessments/ad1c0f6b-396b-44a4-924b-7a4c778a13d3" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/assessments/ad1c0f6b-396b-44a4-924b-7a4c778a13d3</a>, also seen published at assessment ID <code>60c02533-b280-4dec-ac5f-3f10cdd238b9</code> in a second Learn citation — both resolve to the same &quot;Complete the Microsoft FinOps Review&quot; call to action), ~35 minutes, multiple-choice/multiple-response, described as <em>&quot;a lightweight, self-guided assessment&quot;</em> to <em>&quot;identify capability gaps.&quot;</em></p><p>Its subject is the <strong>FinOps Framework</strong>, published in full by Microsoft (<a href="https://learn.microsoft.com/cloud-computing/finops/framework/finops-framework" target="_blank" rel="noreferrer">https://learn.microsoft.com/cloud-computing/finops/framework/finops-framework</a>), attributed to the FinOps Foundation. The framework organises <strong>22 capabilities</strong> into 4 domains — 3 operational domains (Understand usage and cost, Quantify business value, Optimize usage and cost) plus one practice-management domain (Manage the FinOps practice). This enumeration is built from that published capability list.</p><h2 id="verification-method-—-and-the-one-thing-this-enumeration-is-not" tabindex="-1">Verification method — and the one thing this enumeration is NOT <a class="header-anchor" href="#verification-method-—-and-the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;Verification method — and the one thing this enumeration is NOT&quot;">​</a></h2><p><strong>What was read (2026-08-01):</strong></p><table tabindex="0"><thead><tr><th>Source</th><th>What it gave</th></tr></thead><tbody><tr><td>The FinOps Review assessment landing page</td><td>Confirms the assessment exists, its duration/format, and that it is self-guided against the FinOps Framework. <strong>No question text.</strong></td></tr><tr><td><a href="https://learn.microsoft.com/cloud-computing/finops/framework/capabilities" target="_blank" rel="noreferrer">FinOps capabilities</a></td><td>The full 22-capability, 4-domain structure enumerated below</td></tr><tr><td><a href="https://learn.microsoft.com/cloud-computing/finops/framework/optimize/optimize-cloud-usage-cost" target="_blank" rel="noreferrer">Optimize usage and cost</a></td><td>Per-capability definitions for the Optimize domain</td></tr><tr><td><a href="https://learn.microsoft.com/cloud-computing/finops/framework/quantify/quantify-business-value" target="_blank" rel="noreferrer">Quantify business value</a></td><td>Per-capability definitions for the Quantify domain</td></tr><tr><td><code>src/collect/Get-ScoutCostInventory.ps1</code>, <code>src/analyze/Get-ScoutCostAnomaly.ps1</code></td><td>Ground truth for what cost data Scout actually collects and computes, versus what is merely available as an unused function — read directly, not inferred from the audit</td></tr></tbody></table><p><strong>⚠️ The assessment&#39;s own question TEXT and NUMBERS are not published.</strong> The <code>FINOPS-*</code> identifiers below are <strong>Scout&#39;s own</strong>, built from the FinOps Framework&#39;s published capability names — Microsoft attributes the framework itself to the FinOps Foundation, not to the assessment.</p><p><strong>Shelf life.</strong> The FinOps Framework and FinOps toolkit ship monthly releases (see the toolkit&#39;s own roadmap page); re-verify before quoting.</p><h2 id="the-enumeration" tabindex="-1">The enumeration <a class="header-anchor" href="#the-enumeration" aria-label="Permalink to &quot;The enumeration&quot;">​</a></h2><h3 id="understand-usage-and-cost" tabindex="-1">Understand usage and cost <a class="header-anchor" href="#understand-usage-and-cost" aria-label="Permalink to &quot;Understand usage and cost&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>FINOPS-U01</td><td>Cost and usage data is ingested from the cloud provider (and ideally other sources) into a single accessible repository</td><td>⚠️ Partial — <code>src/collect/Get-ScoutCostInventory.ps1</code> (per-subscription cost grouped by type/resource group/location/service) exists but is <strong>opt-in</strong>: it requires <code>Az.CostManagement</code>, which is deliberately excluded from Scout&#39;s core manifest dependencies because installing it can force an incompatible <code>Az.Accounts</code> upgrade. No non-Azure source is ever ingested.</td></tr><tr><td>FINOPS-U02</td><td>Cost is allocated meaningfully — broken down by tag, resource group, or business unit</td><td>⚠️ Partial — cost is grouped by resource group/location/service/type per subscription; that grouping is not joined to <code>$.tags[*]</code>, so tag-based allocation is not currently possible from the same dataset</td></tr><tr><td>FINOPS-U03</td><td>Cost and usage data is reported on and made visible to stakeholders</td><td>⚠️ Partial — a &quot;Costs&quot; worksheet is produced via <code>Start-AZTIExtractionOrchestration.ps1</code>, but that call path is separate from the unified <code>-Assessment</code> entry point&#39;s <code>collect.json</code>, so no rule can currently query it</td></tr><tr><td>FINOPS-U04</td><td>Anomalies (spikes, unexpected changes) are proactively identified and reacted to</td><td>⚠️ Partial — <code>src/analyze/Get-ScoutCostAnomaly.ps1</code> implements three independent detection techniques (spike, z-score, IQR) against <code>Get-ScoutCostInventory</code> output, but nothing in <code>Invoke-Collect.ps1</code> calls it — the capability is built, not wired in</td></tr></tbody></table><h3 id="quantify-business-value" tabindex="-1">Quantify business value <a class="header-anchor" href="#quantify-business-value" aria-label="Permalink to &quot;Quantify business value&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>FINOPS-Q01</td><td>Cost and usage of new or changing workloads is predicted before deployment</td><td>❌ Not collected — no pre-deployment cost-estimation data source</td></tr><tr><td>FINOPS-Q02</td><td>Future cost is forecast from historical trends</td><td>✅ <code>Management/Budgets</code> (&quot;Forecast Spend&quot; field)</td></tr><tr><td>FINOPS-Q03</td><td>Budgets are actively monitored and managed, with alerts configured</td><td>✅ <code>Management/Budgets</code> (&quot;Amount&quot;, &quot;Current Spend&quot;, &quot;Budget Used %&quot;, &quot;Alerts Configured&quot;)</td></tr><tr><td>FINOPS-Q04</td><td>Cloud efficiency is benchmarked against internal teams or industry peers</td><td>❌ Not collected — no benchmarking dataset</td></tr><tr><td>FINOPS-Q05</td><td>Unit economics (cost per business unit of value) are calculated</td><td>❌ Not collected — requires business-metric data outside Azure&#39;s control plane</td></tr></tbody></table><h3 id="optimize-usage-and-cost" tabindex="-1">Optimize usage and cost <a class="header-anchor" href="#optimize-usage-and-cost" aria-label="Permalink to &quot;Optimize usage and cost&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>FINOPS-O01</td><td>Cloud solutions are architected for cost efficiency during design/migration, not retrofitted after deployment</td><td>❌ Design-time decision, not observable post-deployment</td></tr><tr><td>FINOPS-O02</td><td>Workload cost/usage is analyzed to identify efficiency opportunities</td><td>✅ <code>$.advisor[?(@.Category == &#39;Cost&#39;)]</code>, <code>$.costCleanup.orphanedDisks[*]</code>, <code>$.costCleanup.orphanedPips[*]</code></td></tr><tr><td>FINOPS-O03</td><td>Rate optimization is pursued — reservations, savings plans, commitment-discount planning</td><td>✅ <code>General/Reservations</code>, <code>General/ReservationRecom</code></td></tr><tr><td>FINOPS-O04</td><td>Software licenses and prepaid SaaS products (including Azure Hybrid Benefit) are tracked and fully utilized</td><td>❌ Not collected — no license/AHB-flag field on any current collector</td></tr><tr><td>FINOPS-O05</td><td>Carbon emissions are measured alongside cost as part of cloud sustainability</td><td>❌ Not collected — Scout has no Emissions/Carbon API collector</td></tr></tbody></table><h3 id="manage-the-finops-practice" tabindex="-1">Manage the FinOps practice <a class="header-anchor" href="#manage-the-finops-practice" aria-label="Permalink to &quot;Manage the FinOps practice&quot;">​</a></h3><p>This domain is almost entirely organisational — it describes running and maturing the FinOps practice itself, not the resources it manages.</p><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>FINOPS-M01</td><td>A FinOps education and enablement programme exists</td><td>❌ Organisational</td></tr><tr><td>FINOPS-M02</td><td>FinOps practice operations (cadence, ownership, processes) are defined</td><td>❌ Organisational</td></tr><tr><td>FINOPS-M03</td><td>Workloads are onboarded to the FinOps practice based on financial/technical feasibility</td><td>❌ Organisational</td></tr><tr><td>FINOPS-M04</td><td>FinOps-specific policy and governance (cost-allocation tagging, spend guardrails) is enforced</td><td>⚠️ Partial — <code>$.tags[*]</code>, <code>Management/PolicyAssignments</code> are generic governance signals, not FinOps-specific enforcement</td></tr><tr><td>FINOPS-M05</td><td>Invoices are reconciled and cross-charged (chargeback/showback) to internal teams</td><td>❌ Not collected — same billing-hierarchy gap <code>caf.billing.yaml</code>&#39;s misnaming note documents (EA/MCA enrollment, invoice sections)</td></tr><tr><td>FINOPS-M06</td><td>The FinOps practice&#39;s own maturity is periodically reassessed</td><td>❌ Organisational — this is the meta-capability describing running assessments like this one</td></tr><tr><td>FINOPS-M07</td><td>FinOps tools and services are selected and integrated to fit organizational needs</td><td>❌ Organisational/tooling choice</td></tr><tr><td>FINOPS-M08</td><td>FinOps practices are aligned with intersecting frameworks (ITAM, ITSM, security)</td><td>❌ Organisational</td></tr></tbody></table><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p><strong>4 of 22 items are fully answerable, 6 are partial, 12 are organisational or entirely uncollected.</strong> The Manage domain (8 capabilities) is close to a hard floor — only tagging/policy gives any automatable signal at all, and even that is generic governance data repurposed, not FinOps-specific. The more consequential finding is upstream of any rule file: <strong><code>Get-ScoutCostInventory</code> is gated behind an opt-in module Scout deliberately does not install</strong>, so <code>FINOPS-U01</code> through <code>FINOPS-U04</code> — the entire &quot;Understand usage and cost&quot; domain, which every other Optimize/Quantify capability ultimately depends on — is only ever partial in an environment where an operator has separately installed <code>Az.CostManagement</code>. Wiring <code>Get-ScoutCostAnomaly</code> into the collect pipeline (<code>FINOPS-U04</code>) is cheap once that module is present — the detection logic already exists and is tested — but it is downstream of that same dependency decision, not an independent piece of work.</p>',24)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
